mapper.select:
SELECT lca.contract_attachment_id , lca.contract_id , lca.document_name , lca.attachment_code, lca.order_number, ( SELECT wm_concat(sf.FILE_NAME) FROM sys_file sf , sys_attachment sa WHERE sa.ATTACHMENT_ID = sf.ATTACHMENT_ID AND lca.contract_attachment_id = sa.SOURCE_KEY AND sa.SOURCE_TYPE = 'LON_CONTRACT_ATTACHMENT' ) file_names , lca.description, lca.is_final_print, lca.stamp_name, lca.copies, lca.org_stamp_name, lca.np_stamp_name FROM lon_contract_attachment lca
lca.contract_id = #{contractId,jdbcType=BIGINT}
AND lca.contract_attachment_id = #{contractAttachmentId}

select tt.*, ( SELECT wm_concat( fa.file_name ) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi fam WHERE fa.attachment_id = fam.attachment_id AND fam.table_name = 'LON_CONTRACT_ATTACHMENT' AND tt.CONTRACT_ATTACHMENT_ID = fam.table_pk_value ) file_name from lon_contract_attachment tt
1=1
and tt.contract_id = #{contractId}

SELECT t1.document_name, t2.file_id, t2.file_name, t2.file_type, t2.upload_date, t2.file_size, t1.contract_attachment_id, t1.source_type, t1.contract_id, t1.description, t1.is_final_print, t1.stamp_name, t1.copies, t1.org_stamp_name, t1.np_stamp_name, t1.attachment_code, t1.order_number, (SELECT su.description FROM sys_user su WHERE su.user_id = t2.last_updated_by) uploadPerson FROM ( SELECT lca.document_name,lca.contract_attachment_id,lca.contract_id,lca.source_type, lca.description,lca.source_id,lca.is_final_print, lca.stamp_name, lca.copies, lca.org_stamp_name, lca.np_stamp_name, lca.attachment_code, lca.creation_date, lca.order_number, (SELECT a.attachment_id FROM sys_attachment a WHERE cast(a.SOURCE_KEY as char(500))=cast(lca.contract_id as char(500)) AND a.source_type = #{sourceType}) attachment_id FROM lon_contract_attachment lca
lca.contract_id = #{contractId} and lca.source_id is not null
and lca.attachment_status = #{attachmentStatus}
and lca.attachment_type = #{attachmentType}
) t1 LEFT JOIN (select sf.file_id , sf.file_name , sf.file_type , sf.upload_date , sf.file_size , sa.SOURCE_TYPE, sa.SOURCE_KEY, sf.LAST_UPDATED_BY from sys_file sf,sys_attachment sa where sf.attachment_id = sa.attachment_id and sa.source_type = 'LON_CONTRACT_ATTACHMENT') t2 ON t2.file_id = t1.source_id order by t1.order_number,t1.creation_date
